import os, pty, subprocess, select, time, fcntl, termios, struct, signal

def start(args=(), term='xterm', size=(12,30), env=None, path='./executable'):
    master, slave = pty.openpty()
    fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',*size,0,0))
    def preexec():
        os.setsid()
        fcntl.ioctl(0,termios.TIOCSCTTY,0)
    en = dict(os.environ,TERM=term)
    if env: en.update(env)
    p = subprocess.Popen([path]+list(args), stdin=slave, stdout=slave, stderr=slave,env=en,preexec_fn=preexec)
    os.close(slave)
    return p,master

def collect(p,m,seconds,events=()):
    now=time.monotonic(); end=now+seconds; ev=list(events); packets=[]
    while time.monotonic()<end:
        elapsed=time.monotonic()-now
        while ev and elapsed>=ev[0][0]:
            os.write(m,ev.pop(0)[1])
        if select.select([m],[],[],.002)[0]:
            try: data=os.read(m,65536)
            except OSError: break
            if not data: break
            packets.append((time.monotonic()-now,data))
        if p.poll() is not None: break
    return packets

def stop(p,m):
    if p.poll() is None:
        p.kill();p.wait()
    os.close(m)

if __name__=='__main__':
    import sys
    p,m=start(sys.argv[1:]); packets=collect(p,m,.6,[(.48,b'q')]);stop(p,m)
    for t,d in packets: print(round(t,4),repr(d))
