import re,unicodedata
class Screen:
    def __init__(self,rows,cols):
        self.rows,self.cols=rows,cols;self.y=self.x=0;self.fg=self.bg=-1;self.bold=False;self.attrs=0;self.top=0;self.bottom=rows-1
        self.grid=[[(' ',-1,False) for x in range(cols)] for y in range(rows)]
        self.last=' ';self.saved=(0,0)
    def blank(self):return (' ',-1,False)
    def scroll(self,up=True,n=1):
        for i in range(n):
            if up: self.grid.pop(self.top);self.grid.insert(self.bottom,[self.blank() for _ in range(self.cols)])
            else: self.grid.pop(self.bottom);self.grid.insert(self.top,[self.blank() for _ in range(self.cols)])
    def char(self,c):
        if self.x>=self.cols: self.x=0;self.y+=1
        if self.y>=self.rows: self.scroll();self.y=self.rows-1
        self.grid[self.y][self.x]=(c,self.fg,self.bold);self.x+=1;self.last=c
    def feed(self,data):
        s=data.decode('utf-8',errors='replace') if isinstance(data,bytes) else data;i=0
        while i<len(s):
            c=s[i];i+=1
            if c=='\x1b':
                if i>=len(s): break
                c=s[i];i+=1
                if c=='[':
                    st=i
                    while i<len(s) and not ('@'<=s[i]<='~'):i+=1
                    if i==len(s):break
                    params=s[st:i];ch=s[i];i+=1
                    private=params.startswith('?');params=params.lstrip('?=>')
                    try: a=[int(n) if n else 0 for n in params.split(';')]
                    except: a=[0]
                    n=a[0] or 1
                    if ch in ('H','f'):self.y=min(self.rows-1,max(0,a[0]-1));self.x=min(self.cols-1,max(0,(a[1] if len(a)>1 else 1)-1))
                    elif ch=='G':self.x=min(self.cols-1,n-1)
                    elif ch=='d':self.y=min(self.rows-1,n-1)
                    elif ch=='A':self.y=max(0,self.y-n)
                    elif ch=='B':self.y=min(self.rows-1,self.y+n)
                    elif ch=='C':self.x=min(self.cols-1,self.x+n)
                    elif ch=='D':self.x=max(0,self.x-n)
                    elif ch=='J':
                        for y in range(self.rows):
                            for x in range(self.cols):
                                if a[0] in (2,3) or (a[0]==0 and (y,x)>=(self.y,self.x)) or (a[0]==1 and (y,x)<=(self.y,self.x)): self.grid[y][x]=self.blank()
                    elif ch=='K':
                        for x in range(self.cols):
                            if a[0]==2 or a[0]==0 and x>=self.x or a[0]==1 and x<=self.x:self.grid[self.y][x]=self.blank()
                    elif ch in 'LM':
                        for j in range(n):
                            if ch=='L':self.grid.pop(self.bottom);self.grid.insert(self.y,[self.blank() for _ in range(self.cols)])
                            else:self.grid.pop(self.y);self.grid.insert(self.bottom,[self.blank() for _ in range(self.cols)])
                    elif ch=='r':self.top=max(0,n-1);self.bottom=min(self.rows-1,(a[1] or self.rows)-1) if len(a)>1 else self.rows-1;self.y=self.x=0
                    elif ch=='b':
                        for j in range(n):self.char(self.last)
                    elif ch=='X':
                        for x in range(self.x,min(self.cols,self.x+n)):self.grid[self.y][x]=self.blank()
                    elif ch=='P':
                        for j in range(min(n,self.cols-self.x)):self.grid[self.y].pop(self.x);self.grid[self.y].append(self.blank())
                    elif ch=='@':
                        for j in range(n):self.grid[self.y].insert(self.x,self.blank());self.grid[self.y].pop()
                    elif ch=='m':
                        for v in a:
                            if v==0:self.fg=self.bg=-1;self.bold=False
                            elif v==1:self.bold=True
                            elif v==22:self.bold=False
                            elif v==39:self.fg=-1
                            elif v==49:self.bg=-1
                            elif 30<=v<=37:self.fg=v-30
                            elif 40<=v<=47:self.bg=v-40
                    elif ch=='s':self.saved=(self.y,self.x)
                    elif ch=='u':self.y,self.x=self.saved
                elif c in '()':i+=1
                elif c in ('7','8'):
                    if c=='7':self.saved=(self.y,self.x)
                    else:self.y,self.x=self.saved
                elif c=='M':
                    if self.y==self.top:self.scroll(False)
                    else:self.y=max(0,self.y-1)
                elif c=='D':
                    if self.y==self.bottom:self.scroll()
                    else:self.y=min(self.rows-1,self.y+1)
                elif c==']':
                    while i<len(s) and s[i] not in '\x07\x1b':i+=1
            elif c=='\r':self.x=0
            elif c=='\n':
                if self.y==self.bottom:self.scroll()
                else:self.y=min(self.rows-1,self.y+1)
            elif c=='\b':self.x=max(0,self.x-1)
            elif c=='\t':self.x=min(self.cols-1,(self.x//8+1)*8)
            elif ord(c)>=32 and c!='\x7f':self.char(c)
    def lines(self):return [''.join(c for c,f,b in row) for row in self.grid]
    def dump(self):return '\n'.join(self.lines())
