cat > .work/frameprobe.py <<'PY'
import os,subprocess,time,ctypes,pickle
from screen import Screen
END=b'\x1b[?12l\x1b[?25h\x1b[H\x1b[2J'
def frames(size=(6,6),n=20,args=(),path='./executable',seed=None):
    if seed is None:
        time.sleep(1-time.time()%1+.02);seed=int(time.time())
    env=dict(os.environ,TERM='xterm',LINES=str(size[0]),COLUMNS=str(size[1]))
    prev=b'';out=[]
    for f in range(n+1):
        r=subprocess.run([path]+list(args)+['-u','0'],input=b'.'*f+b'q',stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env)
        if r.returncode:print('EXIT',r.returncode,r.stderr);break
        data=r.stdout.split(END)[0]
        assert data.startswith(prev),(f,prev[-100:],data[-100:])
        s=Screen(*size);s.feed(data);out.append((data[len(prev):],s.grid));prev=data
    print('Seed',seed,'end time',time.time())
    return seed,out
if __name__=='__main__':
    import sys
    seed,out=frames(args=sys.argv[1:]);lib=ctypes.CDLL(None);lib.srand(seed);nums=[lib.rand() for _ in range(160)]
    print('RANDOM',[(i,v%6,v%3,chr(v%90+33)) for i,v in enumerate(nums[:70])])
    for i,(d,g) in enumerate(out):print(i, [''.join(c for c,f,b in r) for r in g],repr(d) if i>1 else '<init>')
    with open('.work/latestframes.pkl','wb') as f:pickle.dump((seed,out,nums),f)
