        case '!':opt.color=1;break;
        case '@':opt.color=2;break;
        case '#':opt.color=3;break;
        case '$':opt.color=4;break;
        case '%':opt.color=5;break;
        case '^':opt.color=6;break;
        case '&':opt.color=7;break;
        case ')':opt.color=0;break;
