            case 'B':opt.bold=2;break;
            case 'n':opt.bold=-1;break;
            case 'c':opt.japanese=1;break;
            case 'f':opt.force_linux=1;break;
            case 'l':opt.font=1;break;
            case 'L':opt.locked=1;break;
            case 'o':opt.oldstyle=1;break;
            case 's':opt.screensaver=1;break;
            case 'x':opt.xwindow=1;break;
            case 'r':opt.rainbow=1;break;
            case 'm':opt.lambda=1;break;
            case 'k':opt.changing=1;break;
