    for (int s=0;s<c->nstreams;++s) {
        Stream *stream=&c->streams[s];
        int row=stream->age;
        if (row>0 && row<=height) c->cells[row-1].head=0;
        if (row<height) {
            c->cells[row].value=random_character();
            c->cells[row].head=1;
        }
        int tail=row-stream->length-1;
        if (tail>=0 && tail<height) c->cells[tail]=(Cell){32,0};
        ++stream->age;
