    else if (c->oldlength>0) {
        v.value=random_character();
        --c->oldlength;
        if (c->oldhead==0) {v.value='&';v.head=1;}
        else if(c->oldhead==1) v.value='|';
        ++c->oldhead;
    } else {
        c->waiting=rand()%height+1;
        c->oldlength=random_length(); c->oldhead=0;
    }
    c->cells[0]=v;
}
static void render_column(Column *c,int x) {
    static const int rainbow_colors[]={2,4,0,3,6,5};
    for (int y=0;y<height;++y) {
        Cell cell=c->cells[y];
        int color=opt.color;
        if(opt.rainbow) color=rainbow_colors[rand()%6];
        else if(cell.head) color=COLOR_WHITE;
        int strong=(opt.bold==2 || (opt.bold==1 && cell.value%2==0));
        if(cell.head && opt.bold) strong=1;
        attrset(COLOR_PAIR(color) | (strong?A_BOLD:0));
        if(cell.value<0 || cell.value==32) mvaddch(y,x,' ');
        else if(cell.head) mvaddch(y,x,(chtype)cell.value);
        else if(opt.lambda) mvaddstr(y,x,"\316\273");
        else if(opt.japanese) {
            wchar_t text[2]={(wchar_t)cell.value,0};
            mvaddwstr(y,x,text);
        } else mvaddch(y,x,(chtype)cell.value);
        attrset(A_NORMAL);
    }
}
static void draw_message(void) {
    if (!opt.message || !*opt.message) return;
