        int fd=open(opt.tty,O_RDWR);
        if(fd<0) {
            fprintf(stderr,"cmatrix: error: '%s' couldn't be opened: %s.\n",opt.tty,strerror(errno));
            return 1;
        }
        dup2(fd,STDIN_FILENO);dup2(fd,STDOUT_FILENO);
        if(fd>STDERR_FILENO)close(fd);
